mapper.select:
SELECT emp26_init_leave_id AS init_leave_id , emp01_person_id AS person_id , emp26_year AS year , emp01_emp_no AS person_no , f_emp_kor_nm(emp26_person_id) AS person_name , f_cdnm('EmpPosCode', emp03_pos_cd, emp26_company_id, f_sysdate()) AS pos_name , emp26_use_days AS use_days FROM emp26_init_leave INNER JOIN emp01_person ON emp26_person_id = emp01_person_id INNER JOIN emp02_others ON emp26_person_id = emp02_person_id INNER JOIN emp03_trans ON emp26_person_id = emp03_person_id WHERE (emp03_person_id, emp03_trans_date) IN ( SELECT emp03_person_id, MAX(emp03_trans_date) FROM emp01_person INNER JOIN emp03_trans ON emp03_person_id = emp01_person_id WHERE emp01_company_id = #{companyId} AND emp03_trans_date <= f_sysdate() GROUP BY emp03_person_id )
AND emp26_person_id = #{personId}
AND emp26_year = #{year} ORDER BY emp01_emp_no

SELECT COUNT(*)
  FROM emp01_person
 WHERE emp01_company_id = #{companyId}
   AND emp01_person_id  = #{personId}

SELECT COUNT(*)
  FROM emp26_init_leave
 WHERE emp26_company_id    = #{companyId}
   AND emp26_init_leave_id = #{initLeaveId}

mapper.update:
UPDATE emp26_init_leave
   SET emp26_year     = #{year}
     , emp26_use_days = #{useDays}
 WHERE emp26_company_id    = #{companyId}
   AND emp26_init_leave_id = #{initLeaveId}

mapper.delete:
DELETE FROM emp26_init_leave
 WHERE emp26_company_id    = #{companyId}
   AND emp26_init_leave_id = #{initLeaveId}
